+func EvaluateKMSRegionPinning(ctx context.Context, req Request, pol Policy) (Decision, error) {
+  region := resolveKMSRegion(req.KMSKeyARN)
+  if !pol.AllowedRegions.Contains(region) {
+    return DecisionDenied, nil
+  }
+  return DecisionAllowed, nil
+}

